@patch
def reset(
    self: MultiGridEnv, seed: int | None = None, **kwargs) -> tuple[
        dict[AgentID, ObsType]:
        dict[AgentID, dict[str, Any]]]:
    """
    Reset the environment.

    Parameters
    ----------
    seed : int or None
        Seed for random number generator

    Returns
    -------
    observations : dict[AgentID, ObsType]
        Observation for each agent
    infos : dict[AgentID, dict[str, Any]]
        Additional information for each agent
    """
    # super().reset(seed=seed, **kwargs)
    gym.Env.reset(self, seed=seed, **kwargs)
    vspaces.reset_variation_space(self.variation_space, seed, kwargs.get('options'), self.DEFAULT_VARIATIONS)

    # gym.Env.reset replaces self.np_random when seeded,
    # so re-bind the RandomMixin helpers (_rand_int, etc.) to the new generator
    RandomMixin.__init__(self, self.np_random)

    # Reset agents (keeps the joint agent state, so custom agent colors are preserved)
    self.mission_space.seed(seed)
    self.mission = self.mission_space.sample()
    for agent in self.agents:
        agent.reset(mission=self.mission)

    # Generate a new random grid at the start of each episode
    self._gen_grid(self.width, self.height)
    self._apply_variations()

    # Envs may set the mission while generating the grid: keep the agents in sync
    for agent in self.agents:
        agent.mission = self.mission

    # These fields should be defined by _gen_grid
    assert np.all(self.agent_states.pos >= 0)
    assert np.all(self.agent_states.dir >= 0)

    # Check that agents don't overlap with other objects
    for agent in self.agents:
        start_cell = self.grid.get(*agent.state.pos)
        assert start_cell is None or start_cell.can_overlap()

    # Step count since episode start
    self.step_count = 0

    # Return first observation
    observations = self.gen_obs()
    self._goal_infos = self.goal_infos()

    # Render environment
    if self.render_mode == 'human':
        self.render()

    return observations, self._infos()



