@patch
def place_agent(
    self: MultiGridEnv,
    agent: Agent,
    top=None,
    size=None,
    rand_dir=True,
    max_tries=math.inf) -> tuple[int, int]:
    """
    Set agent starting point at an empty position in the grid.
    """
    agent.state.pos = (-1, -1)
    pos = self.place_obj(None, top, size, max_tries=max_tries)
    agent.state.pos = pos

    if rand_dir:
        agent.state.dir = self._rand_int(0, 4)

    return pos

