@patch
def render(self: MultiGridEnv):
    """
    Render the environment.
    """
    img = self.get_frame(self.highlight, self.tile_size, self.agent_pov)

    if self.render_mode == 'human':
        img = np.transpose(img, axes=(1, 0, 2))
        screen_size = (
            int(self.screen_size * min(img.shape[0] / img.shape[1], 1.0)),
            int(self.screen_size * min(img.shape[1] / img.shape[0], 1.0)),
        )
        if self.render_size is None:
            self.render_size = img.shape[:2]
        if self.window is None:
            pygame.init()
            pygame.display.init()
            pygame.display.set_caption(f'stable-marl - {self.__class__.__name__}')
            self.window = pygame.display.set_mode(screen_size)
        if self.clock is None:
            self.clock = pygame.time.Clock()
        surf = pygame.surfarray.make_surface(img)

        # Create background with mission description
        offset = surf.get_size()[0] * 0.1
        # offset = 32 if self.agent_pov else 64
        bg = pygame.Surface(
            (int(surf.get_size()[0] + offset), int(surf.get_size()[1] + offset))
        )
        bg.fill((255, 255, 255))
        bg.blit(surf, (offset / 2, 0))

        bg = pygame.transform.smoothscale(bg, screen_size)

        font_size = 22
        text = str(self.mission)
        font = pygame.freetype.SysFont(pygame.font.get_default_font(), font_size)
        text_rect = font.get_rect(text, size=font_size)
        text_rect.center = bg.get_rect().center
        text_rect.y = bg.get_height() - font_size * 1.5
        font.render_to(bg, text_rect, text, size=font_size)

        self.window.blit(bg, (0, 0))
        pygame.event.pump()
        self.clock.tick(self.metadata['render_fps'])
        pygame.display.flip()

    elif self.render_mode == 'rgb_array':
        return img



